import{_ as l,a0 as n,w as p,s as u,ao as i,I as s,x as t,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"在 Linux 上試試這個 Java 文件管理器 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上試試這個 Java 文件管理器 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上試試這個 Java 文件管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上試試這個 Java 文件管理器 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20221202.1 ⭐️⭐️ Try this Java file manager on Linux","title":"在 Linux 上試試這個 Java 文件管理器","tag":"202212","desc":""},"relativePath":"202212/20221202.1 ⭐️⭐️ Try this Java file manager on Linux.md","filePath":"[post].md"}'),m={name:"202212/20221202.1 ⭐️⭐️ Try this Java file manager on Linux.md"};function f(d,e,J,x,T,v){const a=n("Link");return p(),u("div",null,[e[21]||(e[21]=i('<h1 id="在-linux-上試試這個-java-文件管理器" tabindex="-1">在 Linux 上試試這個 Java 文件管理器 <a class="header-anchor" href="#在-linux-上試試這個-java-文件管理器" aria-label="Permalink to “在 Linux 上試試這個 Java 文件管理器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202212/17/121727uuepuz1q3qhgippd.jpg" alt=""></p><blockquote><p>JFileProcessor 作為一個 Linux 文件管理器，在設計和功能上都採取了極簡理念。</p></blockquote><p>計算機是一個奇特的文件櫃，裏面裝滿了虛擬文件夾和文件，等待着被引用、交叉引用、編輯、更新、保存、複製、移動、重命名和歸類。在本文中，我將介紹一下 Linux 系統的文件管理器。</p><p>在 <ruby>昇陽微系統<rt>Sun Microsystem</rt></ruby> 時代的末期，出現了一種叫做 <ruby>Java 桌面系統<rt>Java Desktop System</rt></ruby> 的東西，奇怪的是它 <em>不是</em> 用 Java 編寫的。相反，它是（根據當時的 sun.com 上的描述）“對集成和優化的桌面軟件的明智選擇，大部分基於開源代碼和開放標準”。它基於 GNOME，帶有辦公套件、電子郵件和日曆應用、即時消息和“Java 技術”。我發現自己在思考用 Java 創建桌面需要什麼。客觀地説，桌面實際上並不包括那麼多東西。一般的共識似乎是桌面由面板、系統托盤、應用菜單和文件管理器組成。</p><p>想像一個實際的 Java 桌面是一個有趣的思維練習。雖然不足以以此為目標啓動一個開源項目，但足以在網絡上快速搜索必要的組件。事實證明，有人用 Java 編寫並維護了一個文件管理器。</p><h3 id="jfileprocessor" tabindex="-1">JFileProcessor <a class="header-anchor" href="#jfileprocessor" aria-label="Permalink to “JFileProcessor”">​</a></h3>',7)),s("p",null,[e[1]||(e[1]=t("我找到的 Java 文件管理器叫做 JFileProcessor，簡稱 JFP。它不僅是用 Java 編寫的，更具體是説是用 ",-1)),r(a,{href:"https://opensource.com/article/20/12/groovy"},{default:o(()=>[...e[0]||(e[0]=[t("Groovy",-1)])]),_:1}),e[2]||(e[2]=t("（一種流行的 Java 腳本語言）進行的一項迷人的實踐。",-1))]),e[22]||(e[22]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/2022-09/jfileprocessor.webp",alt:"Image of the JfileProcessor folders."})],-1)),e[23]||(e[23]=s("p",null,"作為文件管理器，JFileProcessor 在設計和功能上都採用了極簡方式。它允許你查看、打開、移動、複製、剪切或刪除本地系統和遠程系統上的文件。它不是特別定製化的，它沒有如拆分面板或可移動面板等額外功能。除了管理文件外，它沒什麼別的中心主題。JFileProcessor 在某種程度上令人耳目一新，因為它很簡單。這是一個文件管理器，僅此而已。有時這就是你在文件管理器中想要的全部。",-1)),s("p",null,[e[4]||(e[4]=t("我之前寫過關於 ",-1)),r(a,{href:"https://opensource.com/article/22/3/beautify-java-applications"},{default:o(()=>[...e[3]||(e[3]=[t("設置 Java Swing 主題",-1)])]),_:1}),e[5]||(e[5]=t(" 的方式，從技術上講，該技術可以應用於這個開源應用。但是，我認為這個應用的部分魅力在於 OpenSolaris 稱之為 “Blueprint” 的主題。這是 Java 的懷舊外觀，我喜歡以其原生 GUI 外觀運行它，作為對我的 OpenSolaris（現為 OpenIndiana）筆記本電腦的回憶。",-1))]),e[24]||(e[24]=i('<h3 id="用户體驗" tabindex="-1">用户體驗 <a class="header-anchor" href="#用户體驗" aria-label="Permalink to “用户體驗”">​</a></h3><p>除了設計，真正重要的是用户體驗。JFileProcessor 只有三個你日常使用的按鈕：向上、後退和前進。它們未綁定到鍵盤快捷鍵，因此你必須單擊按鈕才能導航（或使用 <code>Tab</code> 鍵選擇按鈕）。在使用圖形應用時，我經常使用鍵盤快捷鍵，所以當我嘗試瀏覽我的系統時，這大大減慢了我的速度。但是，有時我實際上只是懶洋洋地瀏覽文件，因此 JFileProcessor 完全按照我的需要工作。</p><p>JFileProcessor 也有一個搜索組件。只要你設置合理的起始文件夾，搜索就會快速而智能，同時允許使用通配符和正則模式搜索。例如，當我搜索特定的電子書或漫畫檔案或遊戲規則手冊時，或者當我粗略地知道該目錄包含一個項目但懶得一直點擊到目的地址。在子目錄中快速搜索，必然會得到明顯的結果，然後雙擊打開文件，不管我設置了什麼 XDG 偏好（Evince 用於 PDF，Foliate 用於電子書，等等）。</p><p>右鍵單擊任何文件或目錄會彈出上下文菜單。它具有你期望的大部分常見任務：複製、剪切、粘貼、刪除、重命名、新建。它也有一些不錯的額外功能。</p><p><img src="https://opensource.com/sites/default/files/2022-09/jfileprocessor-menu.webp" alt="Right-click context menu in JFileProcessor"></p><p>例如，你可以只將文件名複製到剪貼板或保存文件路徑。你還可以運行一些腳本，包括用於批量重命名文件的腳本、用於對選定文件運行命令的腳本、用於創建 ZIP 或 TAR 存檔的腳本等等。當然，編碼器有多種選擇，包括在當前位置打開終端和打開新的編碼窗口。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>我是 Java 的忠實粉絲。它是一種清晰的語言，具有合理的分隔符和對跨平台兼容性的堅定立場。我喜歡它作為一種語言，我喜歡看到程序員用它創造的東西。</p><p>JFileProcessor 的名字很貼切。這是一種處理文件的有效方法，從某種意義上説，JFileProcessor 為你提供了一個簡單的窗口來查看系統上的文件數據，並允許你以圖形方式與它們進行交互，就像你可能在終端中與它們交互一樣。它不是我用過的最高效的文件管理器，也不是功能最多的一個。然而，這是一個令人愉快的應用，為你提供了文件管理所需的基本工具，其相對較小的代碼庫使你可以在下午閲讀一些精彩的內容。</p><hr>',10)),s("p",null,[e[7]||(e[7]=t("via: ",-1)),r(a,{href:"https://opensource.com/article/22/12/linux-file-manager-jfileprocessor"},{default:o(()=>[...e[6]||(e[6]=[t("https://opensource.com/article/22/12/linux-file-manager-jfileprocessor",-1)])]),_:1})]),s("p",null,[e[12]||(e[12]=t("作者：",-1)),r(a,{href:"https://opensource.com/users/seth"},{default:o(()=>[...e[8]||(e[8]=[t("Seth Kenlon",-1)])]),_:1}),e[13]||(e[13]=t(" 選題：",-1)),r(a,{href:"https://github.com/lkxed"},{default:o(()=>[...e[9]||(e[9]=[t("lkxed",-1)])]),_:1}),e[14]||(e[14]=t(" 譯者：",-1)),r(a,{href:"https://github.com/geekpi"},{default:o(()=>[...e[10]||(e[10]=[t("geekpi",-1)])]),_:1}),e[15]||(e[15]=t(" 校對：",-1)),r(a,{href:"https://github.com/wxy"},{default:o(()=>[...e[11]||(e[11]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[18]||(e[18]=t("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原創編譯，",-1)),r(a,{href:"https://linux.cn/"},{default:o(()=>[...e[17]||(e[17]=[t("Linux中國",-1)])]),_:1}),e[20]||(e[20]=t(" 榮譽推出",-1))])])}const L=l(m,[["render",f]]);export{b as __pageData,L as default};
